ALTER TABLE users ADD COLUMN balance REAL NOT NULL DEFAULT 0; ALTER TABLE users ADD COLUMN ref_code TEXT; ALTER TABLE users ADD COLUMN referred_by INTEGER; ALTER TABLE users ADD COLUMN ref_rewarded INTEGER NOT NULL DEFAULT 0; ALTER TABLE users ADD COLUMN email_verified INTEGER NOT NULL DEFAULT 0; ALTER TABLE users ADD COLUMN totp_secret TEXT; ALTER TABLE users ADD COLUMN totp_on INTEGER NOT NULL DEFAULT 0; ALTER TABLE users ADD COLUMN google_id TEXT; ALTER TABLE users ADD COLUMN line_id TEXT; ALTER TABLE users ADD COLUMN instructions TEXT NOT NULL DEFAULT ''; ALTER TABLE users ADD COLUMN wallet_overflow INTEGER NOT NULL DEFAULT 0; ALTER TABLE users ADD COLUMN auto_renew INTEGER NOT NULL DEFAULT 0; ALTER TABLE users ADD COLUMN plan_period TEXT NOT NULL DEFAULT 'month'; ALTER TABLE users ADD COLUMN reminded_at INTEGER; ALTER TABLE users ADD COLUMN has_password INTEGER NOT NULL DEFAULT 1;
