ALTER TABLE payments ADD COLUMN kind TEXT NOT NULL DEFAULT 'plan'; ALTER TABLE payments ADD COLUMN period TEXT NOT NULL DEFAULT 'month'; ALTER TABLE payments ADD COLUMN coupon TEXT; ALTER TABLE payments ADD COLUMN discount REAL NOT NULL DEFAULT 0; ALTER TABLE payments ADD COLUMN approved_at INTEGER;
